use crabxl::{Cell, CellAddress, CellValue, EditLimits, StyleId, Worksheet};
use std::{io::Cursor, time::Instant};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mode = std::env::args().nth(1).ok_or("Missing mode")?;
    if mode == "export" {
        let start = Instant::now();
        let mut book = crabxl::Workbook::new(crabxl::WorkbookLimits::default())?;
        let id = book.create_sheet("Sheet")?;
        for index in 0..100_000u32 {
            let address = CellAddress::new(index / 10, index % 10)?;
            let value = if index % 10 == 0 { CellValue::DateTime(Box::new(crabxl::ExcelDateTime::from_ymd(2024, 1, 2)?)) } else { CellValue::Integer(index.into()) };
            book.sheet_mut(id)?.set(Cell { address, value, style: StyleId::new(0) })?;
            if index % 10 == 0 { book.sheet_mut(id)?.set_style(address, StyleId::new(0))?; }
        }
        let writer = crabxl::WorkbookWriter::from_workbook(crabxl::WriteOptions::default(), book)?;
        let output = writer.finish(Cursor::new(Vec::new()))?;
        let seconds = start.elapsed().as_secs_f64();
        let bytes = output.get_ref().len();
        let mut reader = crabxl::WorkbookReader::new(output)?;
        let data = reader.read_sheet("Sheet")?;
        let mut count = 0usize;
        let mut checksum = 0i64;
        for row in data.rows { for cell in row.cells {
            let index = cell.address.row.get() * 10 + cell.address.column.get();
            let expected = if index % 10 == 0 { 45293 } else { i64::from(index) };
            if cell.value != CellValue::Integer(expected) { return Err("Export value/style mismatch".into()); }
            if cell.style.get() != 0 { return Err("Explicit General was replaced".into()); }
            count += 1; checksum += expected;
        }}
        if count != 100_000 { return Err("Export count mismatch".into()); }
        println!("{{\"mode\":\"export\",\"seconds\":{},\"cells\":{},\"checksum\":{},\"output_bytes\":{}}}", seconds, count, checksum, bytes);
        return Ok(());
    }
    let mut sheet = Worksheet::new("Sheet", EditLimits { max_bytes: 1024 * 1024 * 1024, ..Default::default() })?;
    for index in 0..1_000_000u32 {
        let address = CellAddress::new(index / 10, index % 10)?;
        sheet.set(Cell { address, value: CellValue::Integer(index.into()), style: StyleId::new(0) })?;
    }
    let charged = sheet.charged_bytes();
    let start = Instant::now();
    for index in 0..1_000_000u32 {
        let address = CellAddress::new(index / 10, index % 10)?;
        if mode == "direct" { sheet.set_style(address, StyleId::new(1))?; }
        else if mode == "replace" {
            let mut cell = sheet.get(address).ok_or("Missing cell")?.clone();
            cell.style = StyleId::new(1); sheet.set(cell)?;
        } else { return Err("Unknown mode".into()); }
    }
    let seconds = start.elapsed().as_secs_f64();
    let mut checksum = 0i64;
    for cell in sheet.cells() {
        let index = cell.address.row.get() * 10 + cell.address.column.get();
        if cell.style.get() != 1 || cell.value != CellValue::Integer(index.into()) { return Err("Style/value mismatch".into()); }
        checksum += i64::from(index);
    }
    if checksum != 499_999_500_000 || sheet.charged_bytes() != charged { return Err("Storage changed".into()); }
    println!("{{\"mode\":\"{}\",\"seconds\":{},\"cells\":1000000,\"checksum\":{},\"charged_bytes\":{}}}", mode, seconds, checksum, charged);
    Ok(())
}
